function mappingPage(){return `${pageHead('ADMIN · COMPETENCY MAPPING','Find the right trainer','Match a learning need to trainer expertise, evidence and domain experience.',`<span class="pill pill-violet">Explainable matching</span>`)}<section class="panel mapping-search"><span class="eyebrow">WHAT SKILL OR SUBJECT DO YOU NEED?</span><div class="mapping-controls"><select id="mapping-subject"><option>Radar Meteorology</option><option>Data Analysis</option><option>Weather Forecasting</option><option>Climate Science</option></select><select id="mapping-competency"><option>Radar Interpretation</option><option>Data Analysis</option><option>Decision Making</option><option>Communication</option></select><button class="btn btn-primary" data-action="find-trainers">Find trainers <span>→</span></button></div></section><div id="trainer-match-results">${trainerMatches()}</div>`;}
function trainerMatches(){return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECOMMENDED TRAINERS</span><h3>Strong matches for Radar Meteorology</h3></div><span class="pill pill-mint">3 matches</span></div>${[['Dr. Meera Nair','Radar interpretation · Severe weather','91','Strong domain expertise, 8 years of teaching experience, evidence from 4 radar modules.'],['Dr. K. Sharma','Data analysis · Forecast verification','74','Relevant data-analysis evidence and cross-domain experience with operational forecasting.'],['Dr. R. Iyer','Forecasting · Numerical models','68','Strong forecasting background with applied work in numerical weather prediction.']].map(([n,s,m,r])=>`<article class="match-card">${avatar(n)}<div class="match-person"><b>${esc(n)}</b><small>${esc(s)}</small><button class="link-button" data-action="why-match" data-reason="${esc(r)}">Why this match? →</button></div><div class="match-score"><strong>${m}%</strong><small>SKILL MATCH</small></div><button class="btn btn-secondary btn-small" data-action="assign-trainer" data-name="${esc(n)}">View profile</button></article>`).join('')}</section>`;}
function orgCompetencyPage(){return `${pageHead('ORGANIZATION INSIGHTS','Organization competency','A sample view of strengths and growth areas across teams.',`<span class="pill">Illustrative demo data</span>`)}<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-heading"><div><span class="eyebrow">OVERALL COMPETENCY RADAR</span><h3>Current capability distribution</h3></div></div>${radarChart([['Forecasting',81],['Radar Interpretation',78],['Data Analysis',62],['Decision Making',58],['Communication',76]])}<div class="chart-legend"><span><i class="legend-violet"></i>Current capability</span><span><i class="legend-blue"></i>Target profile</span></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">WORKSPACE SNAPSHOT</span><h3>Learning and capability</h3></div></div><div class="org-stat-grid"><div><strong>428</strong><small>Users</small></div><div><strong>312</strong><small>Trainees</small></div><div><strong>86</strong><small>Trainers</small></div><div><strong>78%</strong><small>Completion</small></div></div></section></div><section class="panel"><div class="panel-heading"><div><span class="eyebrow">AREAS TO SUPPORT</span><h3>Where focused learning may help</h3></div><button class="link-button" data-go="Competency Mapping">Find a trainer →</button></div>${[['Data Analysis',62,78],['Decision Making',58,80],['Radar Interpretation',78,85]].map(([n,c,t])=>`<div class="gap-row"><span>${n}</span><b>${c}%</b><span>Target ${t}%</span><strong class="gap-negative">${c-t}</strong></div>`).join('')}</section><p class="data-footnote">Illustrative demo data — do not interpret as official or live institutional metrics.</p>`;}
function analyticsPage(){return `${pageHead('ORGANIZATION INSIGHTS','Learning analytics','Sample engagement and competency trends for the demo workspace.',`<button class="btn btn-quiet" data-action="download-summary">${icon('file')} Export summary</button>`)}<div class="stat-grid"><article class="stat-card"><span class="eyebrow">COURSE COMPLETION</span><strong>78%</strong><span class="card-note">↑ 12% from last quarter</span></article><article class="stat-card"><span class="eyebrow">ASSESSMENT AVERAGE</span><strong>76%</strong><span class="card-note">Across 214 attempts</span></article><article class="stat-card"><span class="eyebrow">ACTIVE LEARNERS</span><strong>284</strong><span class="card-note">91% of enrolled trainees</span></article><article class="stat-card"><span class="eyebrow">SKILLS VALIDATED</span><strong>196</strong><span class="card-note">By trainer review</span></article></div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-heading"><div><span class="eyebrow">LEARNING MOMENTUM</span><h3>Completion by month</h3></div></div>${barChart([48,55,59,64,69,78],['Apr','May','Jun','Jul','Aug','Sep'])}</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SKILL DEVELOPMENT</span><h3>Competency overview</h3></div></div>${Object.entries(seedCompetencies).slice(0,5).map(([n,v])=>`<div class="competency-row"><span>${n}</span>${progress(v)}<b>${v}%</b></div>`).join('')}</section></div><p class="data-footnote">All figures on this page are illustrative sample values.</p>`;}
function usersPage(){return `${pageHead('WORKSPACE ADMIN','Users','Manage the demo workspace roster and role access.',`<button class="btn btn-primary" data-action="invite-user">${icon('plus')} Invite user</button>`)}<section class="panel table-panel"><div class="table-toolbar"><label class="search-box">${icon('search')}<input id="people-search" placeholder="Search users..."/></label><select class="simple-select"><option>All roles</option><option>Trainee</option><option>Trainer</option><option>Admin</option></select></div><div class="table-scroll"><table><thead><tr><th>NAME</th><th>ROLE</th><th>DEPARTMENT</th><th>STATUS</th><th></th></tr></thead><tbody>${seedUsers.map(u=>`<tr><td><div class="table-person">${avatar(u.name)}<span><b>${esc(u.name)}</b><small>${u.role==='Admin'?'admin@imd.gov.in':u.name.toLowerCase().replace(' ','.')+'@imd.gov.in'}</small></span></div></td><td><span class="pill">${u.role}</span></td><td>${esc(u.department)}</td><td><span class="status status-green">${u.status}</span></td><td><button class="link-button" data-action="view-person" data-name="${esc(u.name)}">Details →</button></td></tr>`).join('')}</tbody></table></div><div class="table-footnote">Showing sample users. Invite and identity management require a connected backend.</div></section>`;}
function trainersPage(){return `${pageHead('TRAINER DIRECTORY','Trainers','Find instructors by domain knowledge and validated experience.',`<button class="btn btn-quiet" data-go="Competency Mapping">${icon('link')} Competency mapping</button>`)}<section class="panel">${seedUsers.filter(x=>x.role==='Trainer').map(u=>`<div class="trainer-directory-row">${avatar(u.name,'mint')}<div><b>${esc(u.name)}</b><small>${esc(u.department)} · 8 years teaching</small><span class="skill-tags"><i>Radar Interpretation</i><i>Data Analysis</i><i>Forecasting</i></span></div><div class="match-score"><strong>${u.score}%</strong><small>PROFILE MATCH</small></div><button class="btn btn-secondary btn-small" data-action="view-person" data-name="${esc(u.name)}">View</button></div>`).join('')}</section>`;}
function questionnairePage(){return `${pageHead('ASSESSMENT BUILDER','Create a questionnaire','Add a short knowledge check for your course or learning group.',`<span class="pill">Multiple choice</span>`)}<form class="panel form-panel" id="question-form"><label class="field"><span>Question</span><input id="question-title" placeholder="Enter a clear question" required/></label><div class="form-grid">${[1,2,3,4].map(i=>`<label class="field"><span>Option ${i}</span><input placeholder="Answer option ${i}" ${i===1?'required':''}/></label>`).join('')}</div><label class="field"><span>Correct answer</span><select><option>Option 1</option><option>Option 2</option><option>Option 3</option><option>Option 4</option></select></label><label class="field"><span>Competency assessed</span><select><option>Radar Interpretation</option><option>Data Analysis</option><option>Decision Making</option><option>Communication</option></select></label><div class="panel-actions"><button class="btn btn-quiet" type="button" data-action="clear-form">Clear</button><button class="btn btn-primary">Save question <span>→</span></button></div></form>`;}
function libraryPage(){return `${pageHead('TRAINER LIBRARY','Learning resources','A small sample library of reusable learning materials.',`<button class="btn btn-quiet" data-action="add-resource">${icon('upload')} Add resource</button>`)}<div class="tabs library-tabs">${['Videos','PDFs','Docs'].map((t,i)=>`<button class="tab ${(!state.libraryTab&&i===0)||state.libraryTab===t?'selected':''}" data-action="library-tab" data-tab="${t}">${t}</button>`).join('')}</div><section class="panel library-list">${resourceList()}</section><p class="tiny-muted">File uploads are not wired in this demo. Connect secure storage before adding real learner materials.</p>`;}
function announcementsPage(){return `${pageHead('NEXORA UPDATES','Announcements','Learning updates and important notices for your workspace.',`<button class="btn btn-primary" data-action="create-announcement">${icon('plus')} New announcement</button>`)}<section class="panel"><div class="panel-heading"><div><span class="eyebrow">LATEST UPDATES</span><h3>For the learning community</h3></div><span class="pill">${state.announcements.length} updates</span></div>${state.announcements.slice().reverse().map(a=>`<div class="announcement-card"><span class="announcement-icon">${a.icon}</span><div><span class="eyebrow">WORKSPACE UPDATE · ${esc(a.date)}</span><h3>${esc(a.title)}</h3><p>${esc(a.detail)}</p></div><button class="link-button" data-action="read-announcement">Read →</button></div>`).join('')}</section>`;}
function profilePage(){const role=state.role;return `${pageHead('YOUR ACCOUNT','Profile & Settings','Manage your local demo profile and learning preferences.',`<button class="btn btn-quiet" data-action="switch-role">Switch role</button>`)}<section class="panel profile-hero">${avatar(role==='Trainer'?'Dr. Meera Nair':role==='Admin'?'Institutional Admin':state.profile.name)}<div><span class="eyebrow">${esc(role.toUpperCase())} PROFILE</span><h2>${esc(role==='Trainer'?'Dr. Meera Nair':role==='Admin'?'Institutional Admin':state.profile.name)}</h2><p>${esc(role==='Trainer'?'Weather Forecasting · Senior Scientist':role==='Admin'?'Institutional workspace administrator':state.profile.designation+' · '+state.profile.department)}</p></div><button class="btn btn-secondary btn-small" data-action="edit-profile">Edit profile</button></section><div class="settings-grid"><section class="panel"><span class="eyebrow">PERSONAL INFORMATION</span><h3>Profile details</h3><div class="detail-stat"><span>Employee ID</span><b>${esc(state.profile.employeeId)}</b></div><div class="detail-stat"><span>Department</span><b>${esc(state.profile.department)}</b></div><div class="detail-stat"><span>Designation</span><b>${esc(state.profile.designation)}</b></div><div class="detail-stat"><span>Experience</span><b>${esc(state.profile.experience)}</b></div></section><section class="panel"><span class="eyebrow">PREFERENCES</span><h3>Learning and privacy</h3><button class="setting-row" data-action="toggle-notifications"><span><b>Learning reminders</b><small>Gentle reminders about your next step</small></span><i class="toggle ${state.reminders===false?'off':''}"></i></button><button class="setting-row" data-action="privacy-info"><span><b>Privacy & security</b><small>Demo data stays in this browser</small></span><span>›</span></button><button class="setting-row danger" data-action="reset-demo"><span><b>Reset demo progress</b><small>Clear this browser's prototype progress</small></span><span>↺</span></button></section></div><button class="btn btn-outline logout-button" data-action="logout">${icon('back')} Return to welcome screen</button>`;}
function copilot(){return `<div class="copilot-overlay" id="copilot-overlay"><aside class="copilot-panel"><header><div class="copilot-title"><span class="copilot-mark">✦</span><div><b>Nexora Co-pilot</b><small>DEMO · EXPLAINABLE GUIDANCE</small></div></div><button class="icon-button" data-action="close-copilot">×</button></header><div class="copilot-thread" id="copilot-thread"><div class="copilot-message bot"><span class="bot-icon">✦</span><div><small>NEXORA CO-PILOT</small><p>Hi ${esc((state.profile.name||'Aarav').split(' ')[0])}. I can help you understand your competency profile and choose a next step. What would you like to work on?</p></div></div><div class="quick-prompts">${['What should I learn next?','Show my skill gaps','Open my learning path','Find a trainer for radar'].map((p,i)=>`<button data-action="copilot-prompt" data-prompt="${esc(p)}"><span>${['✦','◈','⌁','♙'][i]}</span>${p}</button>`).join('')}</div></div><form class="copilot-input" id="copilot-form"><input id="copilot-text" placeholder="Ask about your learning..."/><button aria-label="Send question">➤</button></form><div class="copilot-disclaimer">Deterministic sample guidance · No live AI connected</div></aside></div>`;}
function modal(content,title='Nexora'){const root=$('#modal-root');if(!root)return;root.hidden=false;root.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-content">${content}</div></section>`;wireGlobal();setTimeout(()=>root.querySelector('input,button')?.focus(),40);}
function closeModal(){$('#modal-root').hidden=true;$('#modal-root').innerHTML='';}
function copilotReply(prompt){const low=prompt.toLowerCase(),data=state.competencies['Data Analysis']||48,radar=state.competencies['Radar Interpretation']||72;if(low.includes('gap')||low.includes('skill'))return `Your sample profile shows Data Analysis at ${data}% against a target of 70%, which makes it the largest current gap. Radar Interpretation is ${radar}%. A short data-analysis module followed by Mission 02 would give you both learning practice and applied evidence.`;if(low.includes('trainer')||low.includes('radar'))return 'Dr. Meera Nair is the strongest sample match for Radar Meteorology. The demo match is based on radar domain expertise, teaching experience and evidence across radar modules. Open Competency Mapping to compare trainer profiles.';if(low.includes('path')||low.includes('next')||low.includes('learn'))return 'Your next suggested step is Data Analysis Module 3. It addresses the largest gap in your current sample profile. After that, try Mission 02 to apply your learning and add decision-making evidence.';return 'Based on your current demo profile, I suggest continuing Data Analysis Module 3, then practising in Mission 02. This guidance is generated from sample competency values in your browser, not a live AI model.';}
function render(){const root=$('#app');if(!root)return;if(!state.role){root.innerHTML=page();wireGlobal();return;}root.innerHTML=shell();wireGlobal();const route=state.route;if(route==='Courses'&&state.selectedCourse){} if($('#people-search'))$('#people-search').addEventListener('input',e=>filterPeople(e.target.value));if($('#course-search'))$('#course-search').addEventListener('input',e=>{state.courseSearch=e.target.value;const y=window.scrollY,active=document.activeElement.selectionStart;const parent=$('#content');if(parent){const next=parent.querySelector('.course-grid');const filtered=courses.filter(c=>(activeFilter==='All'||c.subject===activeFilter)&&c.title.toLowerCase().includes(state.courseSearch.toLowerCase()));next.innerHTML=filtered.map(c=>courseCard(c)).join('')||'<div class="empty-state">No courses match that search yet.</div>';document.querySelectorAll('[data-action="course-detail"]').forEach(b=>b.addEventListener('click',onAction));}});if($('#mission-response'))$('#mission-response').addEventListener('input',e=>{state.missionResponse=e.target.value;saveState();$('#char-count').textContent=`${e.target.value.length} / 600`;});if(!$('#copilot-overlay')&&state.copilotOpen){document.body.insertAdjacentHTML('beforeend',copilot());wireGlobal();}}
function wireGlobal(){document.querySelectorAll('[data-go]').forEach(b=>{if(b.dataset.wired)return;b.dataset.wired='1';b.addEventListener('click',()=>go(b.dataset.go));});document.querySelectorAll('[data-action]').forEach(b=>{if(b.dataset.wired)return;b.dataset.wired='1';b.addEventListener('click',onAction);});const login=$('#login-form');if(login&&!login.dataset.wired){login.dataset.wired='1';login.addEventListener('submit',e=>{e.preventDefault();signIn();});}const q=$('#question-form');if(q&&!q.dataset.wired){q.dataset.wired='1';q.addEventListener('submit',e=>{e.preventDefault();toast('Question saved to the local demo draft.');q.reset();});}const cf=$('#course-form');if(cf&&!cf.dataset.wired){cf.dataset.wired='1';cf.addEventListener('submit',e=>{e.preventDefault();const v=cf.querySelectorAll('input'),title=v[0]?.value.trim();if(!title){toast('Add a course title first.');return;}const c={title,subject:v[1]?.value||'Learning',level:v[2]?.value||'Beginner',duration:v[3]?.value||'2h',modules:1,teacher:'Dr. Meera Nair',rating:'New',image:'data',description:cf.querySelector('textarea')?.value||'A trainer-created sample course.',skills:['Build domain understanding','Practise with examples']};state.courses=[c,...state.courses];saveState();toast('Course saved to your demo workspace.');go('My Courses');});}const cf2=$('#copilot-form');if(cf2&&!cf2.dataset.wired){cf2.dataset.wired='1';cf2.addEventListener('submit',e=>{e.preventDefault();sendCopilot();});}}
function signIn(){const role=state.pendingRole||'Trainee';state.role=role;state.route=role==='Trainee'?'Home':role==='Trainer'?'Home':'Dashboard';state.copilotOpen=false;saveState();render();toast(`Welcome to the ${role.toLowerCase()} demo workspace.`);}
function onAction(e){const a=e.currentTarget.dataset.action;if(a==='get-started')go('Role Selection');else if(a==='explore')modal(`<p>Nexora connects learning, scenario practice and competency evidence in one clear journey.</p><ul class="modal-list"><li>Role-based learning workspace</li><li>Applied missions with transparent rubrics</li><li>Competency gaps and explainable guidance</li></ul><button class="btn btn-primary btn-wide" data-action="modal-start">Explore the demo <span>→</span></button>`,'Explore Nexora');else if(a==='modal-start'){closeModal();go('Role Selection');}else if(a==='choose-role'){state.pendingRole=e.currentTarget.dataset.role;go(state.pendingRole==='Admin'?'Admin Login':'Login / Sign Up');}else if(a==='demo-signin')signIn();else if(a==='forgot')toast('Password recovery needs an account service; use demo access here.');else if(a==='course-detail'){state.selectedCourse=e.currentTarget.dataset.course;courseTab='Overview';go('Courses');}else if(a==='course-tab'){courseTab=e.currentTarget.dataset.tab;render();}else if(a==='filter-course'){activeFilter=e.currentTarget.dataset.filter;render();}else if(a==='enroll'){const c=e.currentTarget.dataset.course;if(!state.enrolled.includes(c))state.enrolled.push(c);state.selectedCourse=null;saveState();toast('You are enrolled in the demo course.');go('Learning Path');}else if(a==='resource')toast('Sample resource preview is ready for backend connection.');else if(a==='start-module'){state.completedModules=Math.min(6,state.completedModules+1);state.competencies['Data Analysis']=Math.min(100,(state.competencies['Data Analysis']||48)+2);state.events.push({date:'Sep 28',label:'Module completed',detail:'Data Analysis Module 3',change:'+2%'});saveState();toast('Module complete. Sample capability updated.');go('Learning Path');}else if(a==='locked-step')toast('Complete the current module to unlock this step.');else if(a==='select-answer'){selectedAnswer=Number(e.currentTarget.dataset.answer);render();}else if(a==='next-question'){assessmentIndex++;if(assessmentIndex>=3){state.assessmentDone=true;state.assessmentScore=78;state.competencies['Radar Interpretation']=Math.min(100,(state.competencies['Radar Interpretation']||72)+2);state.events.push({date:'Sep 28',label:'Assessment completed',detail:'Radar Meteorology Basics',change:'+2%'});saveState();assessmentIndex=0;selectedAnswer=-1;go('Assessment Result');}else{selectedAnswer=-1;render();}}else if(a==='prev-question'){assessmentIndex=Math.max(0,assessmentIndex-1);selectedAnswer=-1;render();}else if(a==='mission-tab'){missionTab=e.currentTarget.dataset.tab;render();}else if(a==='tool-hint')modal(`<p>Use the sample observations, state uncertainty clearly and explain which team should be informed.</p><p class="muted">This is a learning hint, not an operational weather alert.</p>`,'Decision checklist');else if(a==='submit-mission'){const response=($('#mission-response')?.value||'').trim();if(response.length<20){toast('Add a little more reasoning before you submit.');$('#mission-response')?.focus();return;}state.missionResponse=response;state.missionComplete=true;state.missionScore=Math.min(96,66+Math.floor(response.length/15)+(response.toLowerCase().includes('radar')?7:0)+(response.toLowerCase().includes('team')||response.toLowerCase().includes('alert')?6:0));state.competencies['Decision Making']=Math.min(100,(state.competencies['Decision Making']||62)+5);state.competencies['Risk Awareness']=Math.min(100,(state.competencies['Risk Awareness']||66)+3);state.events.push({date:'Sep 28',label:'Mission completed',detail:'Operational Decision Making',change:'+8%'});saveState();go('Mission Result');}else if(a==='open-copilot'){state.copilotOpen=true;document.body.insertAdjacentHTML('beforeend',copilot());wireGlobal();setTimeout(()=>$('#copilot-text')?.focus(),100);}else if(a==='close-copilot'){document.querySelector('.copilot-overlay')?.remove();state.copilotOpen=false;}else if(a==='copilot-prompt'){const p=e.currentTarget.dataset.prompt;$('#copilot-text').value=p;sendCopilot(p);}else if(a==='select-proof'){state.proofSkill=e.currentTarget.dataset.skill;render();}else if(a==='submit-proof'){if(!state.proofSkill){toast('Choose a competency first.');return;}state.proofSubmitted=true;saveState();render();toast('Skill evidence sent for sample trainer review.');}else if(a==='toggle-twin')toast('Current and target capability are compared in the competency gap view.');else if(a==='share-passport')toast('Passport preview is ready. Sharing link requires a backend.');else if(a==='add-outcome'){document.querySelector('.outcomes-list').insertAdjacentHTML('beforeend',`<div class="outcome-input"><span>+</span><input placeholder="Add another learning outcome" /></div>`);}else if(a==='find-trainers'){const s=$('#mapping-subject').value;$('#trainer-match-results').innerHTML=trainerMatches().replace('Radar Meteorology',esc(s));toast(`Sample trainer matches updated for ${s}.`);wireGlobal();}else if(a==='why-match'){modal(`<div class="match-explanation"><span class="explain-mark">✦</span><p>${esc(e.currentTarget.dataset.reason)}</p></div><div class="guide-stat"><span>Domain relevance</span><b>Strong</b></div><div class="guide-stat"><span>Sample evidence</span><b>Reviewed</b></div><p class="tiny-muted">Match explanation uses illustrative trainer profiles and rule-based demo scoring.</p>`,'Why this trainer matches');}else if(a==='assign-trainer'){modal(`<p><b>${esc(e.currentTarget.dataset.name)}</b> is shown as a strong sample match for this learning request.</p><p class="muted">Trainer assignment and contact require an authenticated organization backend.</p>`,'Trainer profile');}else if(a==='view-person'){modal(`<div class="profile-modal-person">${avatar(e.currentTarget.dataset.name)}<div><h3>${esc(e.currentTarget.dataset.name)}</h3><p class="muted">Sample workspace member</p></div></div><p>Competency evidence and activity details are sample content in this prototype.</p>`,'Workspace profile');}else if(a==='create-announcement'){modal(`<form id="announcement-form">${field('Announcement title','e.g. New learning module available')}${field('Short update','Add useful details')}<button class="btn btn-primary btn-wide">Publish to demo workspace</button></form>`,'New announcement');$('#announcement-form').addEventListener('submit',ev=>{ev.preventDefault();const v=ev.currentTarget.querySelectorAll('input');if(!v[0].value.trim())return;state.announcements.push({title:v[0].value,detail:v[1].value,date:'28 Sep',icon:'✦'});saveState();closeModal();render();toast('Announcement added to the local demo workspace.');});}else if(a==='read-announcement')toast('You are up to date.');else if(a==='add-resource')toast('Connect secure storage to add a learning file.');else if(a==='library-tab'){state.libraryTab=e.currentTarget.dataset.tab;render();}else if(a==='clear-form')$('#question-form')?.reset();else if(a==='invite-user')modal(`<p>Invite flow needs organization sign-in and email delivery. This demo uses sample workspace members.</p><button class="btn btn-primary btn-wide" data-action="close-modal">Got it</button>`,'Invite workspace user');else if(a==='download-summary')toast('Connect the analytics service to export live workspace data.');else if(a==='edit-map')toast('Competency mapping editor is available after backend setup.');else if(a==='edit-profile')modal(`<p>Profile editing will be enabled with authenticated accounts.</p><button class="btn btn-primary btn-wide" data-action="close-modal">Done</button>`,'Edit profile');else if(a==='toggle-notifications'){state.reminders=state.reminders===false?true:false;saveState();render();toast(`Learning reminders ${state.reminders?'enabled':'paused'}.`);}else if(a==='privacy-info')modal(`<p>Your demo profile and progress are saved only in this browser's local storage. Do not enter confidential or personal data into the prototype.</p>`,'Privacy & security');else if(a==='reset-demo')modal(`<p>This clears only Nexora demo progress saved in the current browser and restores the sample profile.</p><div class="panel-actions"><button class="btn btn-quiet" data-action="close-modal">Keep progress</button><button class="btn btn-danger" data-action="confirm-reset">Reset this demo</button></div>`,'Reset local demo progress');else if(a==='confirm-reset'){localStorage.removeItem('nexora-demo-state');state={...defaultState,competencies:{...seedCompetencies},events:[...defaultState.events],announcements:[...seedAnnouncements],enrolled:[],courses:[...courses]};closeModal();render();toast('Demo progress reset.');}else if(a==='switch-role'){state.role=null;state.pendingRole=null;state.route='Role Selection';saveState();render();}else if(a==='logout'){state.role=null;state.route='Welcome';state.copilotOpen=false;saveState();render();}else if(a==='close-modal')closeModal();else if(a==='toggle-menu')document.querySelector('.sidebar')?.classList.toggle('mobile-open');}
function filterPeople(query){document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(query.toLowerCase()));}
function sendCopilot(text){const input=$('#copilot-text'),query=text||(input?.value||'').trim();if(!query)return;const thread=$('#copilot-thread');const escaped=esc(query);thread.insertAdjacentHTML('beforeend',`<div class="copilot-message user"><p>${escaped}</p></div><div class="copilot-message bot"><span class="bot-icon">✦</span><div><small>RULE-BASED DEMO GUIDANCE</small><p>${esc(copilotReply(query))}</p><button class="link-button" data-go="${query.toLowerCase().includes('trainer')?'Competency Mapping':'Learning Path'}">Open related view →</button></div></div>`);if(input)input.value='';thread.scrollTop=thread.scrollHeight;wireGlobal();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('.copilot-overlay')?.remove();state.copilotOpen=false;}});
render();
